using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

var searchApiKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY"); // optional

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tools ---
var notebook = new Notebook();
var webSearcher = new WebSearcher(searchApiKey);

// --- Chat client with automatic tool invocation ---
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(openAiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(webSearcher.SearchWeb),
        AIFunctionFactory.Create(notebook.AddNote),
        AIFunctionFactory.Create(notebook.GetNotes),
    ],
};

// --- Prompt ---
Console.WriteLine("=== AI Research Agent ===");
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching \"{topic}\" …\n");

var systemPrompt = """
    You are a research agent. Your job is to research the topic the user gives you.

    Follow these steps:
    1. Break the topic into 2-3 search queries that cover different angles.
    2. For each query, call the SearchWeb tool to find relevant information.
    3. As you discover important facts, call AddNote to save them.
    4. After finishing your research, call GetNotes to review everything you collected.
    5. Finally, write a concise research summary with sections and cite your sources.

    Be thorough but concise. Always save notes before summarising.
    """;

List<ChatMessage> messages =
[
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic: {topic}"),
];

// --- Agent loop ---
var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine("── Research Summary ──────────────────────────");
Console.WriteLine(response.Text);
Console.WriteLine("──────────────────────────────────────────────");

// --- Tool implementations -----------------------------------------------

/// <summary>Simulated web search tool backed by Brave Search API when available.</summary>
sealed class WebSearcher(string? braveApiKey)
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information. Returns a list of result snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.WriteLine($"  🔍  Searching: \"{query}\"");

        if (!string.IsNullOrEmpty(braveApiKey))
        {
            return await SearchBrave(query, braveApiKey);
        }

        // Fallback: lightweight simulated results so the app works without an API key.
        return await FallbackSearch(query);
    }

    private static async Task<string> SearchBrave(string query, string apiKey)
    {
        var request = new HttpRequestMessage(HttpMethod.Get,
            $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        var resp = await Http.SendAsync(request);
        resp.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(await resp.Content.ReadAsStreamAsync());
        var results = doc.RootElement.GetProperty("web").GetProperty("results");

        var snippets = new List<string>();
        foreach (var r in results.EnumerateArray())
        {
            var title = r.GetProperty("title").GetString();
            var url = r.GetProperty("url").GetString();
            var desc = r.TryGetProperty("description", out var d) ? d.GetString() : "";
            snippets.Add($"- {title}\n  {url}\n  {desc}");
        }

        return snippets.Count > 0
            ? string.Join("\n\n", snippets)
            : "No results found.";
    }

    private static async Task<string> FallbackSearch(string query)
    {
        // Use DuckDuckGo Instant Answer API as a free, keyless fallback.
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        try
        {
            var json = await Http.GetFromJsonAsync<JsonElement>(url);
            var snippets = new List<string>();

            if (json.TryGetProperty("AbstractText", out var abs) &&
                abs.GetString() is { Length: > 0 } abstractText)
            {
                var source = json.TryGetProperty("AbstractURL", out var u)
                    ? u.GetString() : "";
                snippets.Add($"- {abstractText}\n  Source: {source}");
            }

            if (json.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var t in topics.EnumerateArray().Take(4))
                {
                    if (t.TryGetProperty("Text", out var text) &&
                        text.GetString() is { Length: > 0 } s)
                    {
                        var link = t.TryGetProperty("FirstURL", out var fu)
                            ? fu.GetString() : "";
                        snippets.Add($"- {s}\n  Source: {link}");
                    }
                }
            }

            return snippets.Count > 0
                ? string.Join("\n\n", snippets)
                : $"No detailed results found for \"{query}\". Try a more specific query.";
        }
        catch
        {
            return $"Search unavailable. Could not reach search API for \"{query}\".";
        }
    }
}

/// <summary>Simple in-memory notebook the agent uses to collect research findings.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important facts and sources.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝  Note #{_notes.Count} saved.");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n",
            _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }
}

